 if a.validate_report:run('browser/browser.py','--validate-report',a.validate_report.resolve());return
 if a.validate_public_build:run('tools/public_build_receipt.py','--validate',a.validate_public_build.resolve());return
 run('tools/bootstrap.py','--verify-vendor')
 if a.self_test:
  subprocess.run(['node','browser/tests/residency_host.js'],cwd=root,env=env,check=True)
  run('-m','unittest','discover','-s','tools','-p','test_*.py','-v');run('-m','unittest','discover','-s','diagnostic_tests','-p','test_*.py','-v');run('-m','unittest','discover','-s','tests','-p','test_observer.py','-v')
 if not(a.prepare or a.execute_browser):
  run('tools/bootstrap.py','--plan');run('browser/browser.py','--plan');return
 work=a.cache.resolve()/('build-'+PAYLOAD_SHA256[:12]);paths=work/'toolchain-paths.json'
 run('tools/bootstrap.py','--work',work,'--prepare-fixtures')
