 run('tools/build.py','--paths',paths,'--work',work)
 run('tools/public_build_receipt.py','--manifest',work/'build.json','--output',a.private.resolve()/'public-build.json','--require-linked')
 run('browser/browser.py','--manifest',work/'build.json','--verify-inputs')
 if a.execute_browser:run('browser/browser.py','--manifest',work/'build.json','--private',a.private.resolve()/'browser','--execute','--preflight-start-monotonic',preflight_start,'--preflight-origin',preflight_origin)
